UPDATE `message`.`message_template` SET `template_name` = '门店物品库存不足', `template_type` = 'email', `template_subject` = '[Alert] {{company}} - Insufficient Safety Stock of {{material}}!', `template_content` = '\n <!-- 外层容器表格 -->\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #f9f4f0; padding: 64px 16px;\">\n <tr>\n <td align=\"center\" style=\"padding: 0;\">\n <!-- Logo 区域 -->\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width: 560px; margin: 0 auto 24px;\">\n <tr>\n <td align=\"center\" style=\"padding: 0 16px;\">\n <!-- 注意：这里需要替换为实际的 logo 图片 URL -->\n <img src=\"https://wallace-th.s.frappe.cloud/files/banner.png\" alt=\"TTPOS\" width=\"161\" height=\"28\" style=\"display: block; max-width: 161px; height: auto;\" />\n </td>\n </tr>\n </table>\n\n <!-- 主卡片 -->\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width: 560px; margin: 0 auto; background-color: white; border-radius: 12px; border-top: 8px solid #ff6c1f;\">\n <!-- 图标和标题区域 -->\n <tr>\n <td style=\"padding: 36px 16px 0;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td align=\"center\" style=\"padding-bottom: 28px;\">\n <!-- 警告图标 - 使用 Unicode 字符或图片 -->\n <div style=\"width: 160px; height: 160px; margin: 0 auto; background-color: #F7F7F7; border-radius: 50%; position: relative; display: inline-block;\">\n <!-- 或者使用图片 -->\n <img src=\"https://wallace-th.s.frappe.cloud/files/icon.png\" alt=\"Warning\" width=\"160\" height=\"160\" style=\"display: block;\" />\n </div>\n </td>\n </tr>\n <tr>\n <td align=\"center\" style=\"padding-bottom: 28px;\">\n <div style=\"color: #1a202e; font-size: 18px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 700; line-height: 26px;\">\n Inventory Alert\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 正文内容区域 -->\n <tr>\n <td style=\"padding: 0 16px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <!-- 问候语段落 -->\n <tr>\n <td style=\"padding-bottom: 24px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n Dear Management Team of {{company}},\n </div>\n </td>\n </tr>\n <tr>\n <td>\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n The system has detected that the inventory of your store\'s \n <span style=\"color: #333333; font-weight: 700;\">{{material}}</span>\n has fallen below the preset safety stock level. Please arrange for timely replenishment to avoid any impact on normal sales operations.\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 分隔线 -->\n <tr>\n <td style=\"padding-bottom: 24px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"height: 1px; background-color: #ebebeb; opacity: 0.5;\"></td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 详细信息区域 -->\n <tr>\n <td style=\"padding-bottom: 24px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <div style=\"color: #1a202e; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n Alert Details are as follows:​\n </div>\n </td>\n </tr>\n <!-- Material Name -->\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-right: 12px;\">\n <div style=\"color: #333333; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px; white-space: nowrap;\">\n Material Name:\n </div>\n </td>\n <td>\n <div style=\"color: #1a202e; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 500; line-height: 22px;\">\n {{material}}​\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n <!-- Current Store Inventory -->\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-right: 12px;\">\n <div style=\"color: #333333; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px; white-space: nowrap;\">\n Current Store Inventory:\n </div>\n </td>\n <td>\n <div style=\"color: #1a202e; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 500; line-height: 22px;\">\n {{current_stock}}\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n <!-- Preset Safety Stock -->\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-right: 12px;\">\n <div style=\"color: #333333; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px; white-space: nowrap;\">\n Preset Safety Stock:\n </div>\n </td>\n <td>\n <div style=\"color: #1a202e; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 500; line-height: 22px;\">\n {{safety_stock}}\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n <!-- Alert Trigger Time -->\n <tr>\n <td style=\"padding-bottom: 8px;\">\n <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-right: 12px;\">\n <div style=\"color: #333333; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px; white-space: nowrap;\">\n Alert Trigger Time:\n </div>\n </td>\n <td>\n <div style=\"color: #1a202e; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 500; line-height: 22px;\">\n {{time}}\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 分隔线 -->\n <tr>\n <td style=\"padding-bottom: 24px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"height: 1px; background-color: #ebebeb; opacity: 0.5;\"></td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 提示信息 -->\n <tr>\n <td style=\"padding-bottom: 24px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td style=\"padding-bottom: 4px;\">\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n Please instruct the relevant responsible colleagues to verify the inventory immediately and initiate a purchase order. If a purchase order has already been submitted, this email may be ignored.​\n </div>\n </td>\n </tr>\n <tr>\n <td>\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n Thank you for your prompt attention and handling. Best regards!\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n\n <!-- 签名区域 -->\n <tr>\n <td style=\"padding-bottom: 48px;\">\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n <tr>\n <td align=\"right\">\n <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"right\">\n <tr>\n <td style=\"padding-bottom: 4px;\">\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n TTPOS\n </div>\n </td>\n </tr>\n <tr>\n <td>\n <div style=\"color: #767676; font-size: 14px; font-family: Arial, \'HarmonyOS Sans SC\', sans-serif; font-weight: 400; line-height: 22px;\">\n {{date}}\n </div>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n </table>\n </td>\n </tr>\n </table>\n\n', `template_args` = '{\"date\": \"发送日期\", \"time\": \"发送时间\", \"company\": \"公司名称\", \"material\": \"物品名称\", \"safety_stock\": \"安全库存\", \"current_stock\": \"当前库存\"}', `status` = 1, `remark` = '门店物品库存不足模板', `created_at` = 1762854178, `updated_at` = 1762854178, `deleted_at` = 0 WHERE `uuid` = 'tpl_company_safety_stock_alert';
